B.asO=new A.ad("Bu soruyu incelememiz i\xe7in i\u015faretliyoruz. \u0130stersen k\u0131saca ne oldu\u011funu yazabilirsin (opsiyonel).",null,null,null,null,null,null,null,null,null)
B.asP=new A.ad("Okudum, kabul ediyorum",null,null,null,null,null,null,null,null,null)
